const B = "C:\\Users\\jjq21\\Desktop\\github\\My-second-brain";
const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "")) : JSON.stringify(x);
const [mdList, notDone, gitDelta] = await Promise.all([
 tools.pwsh({ command: `Get-ChildItem -Recurse '${B}' -Filter '*.md' -File | Where-Object { $_.FullName -notmatch '\\\\\\.git\\\\' -and $_.FullName -notmatch 'node_modules' } | ForEach-Object { $_.FullName.Replace('${B}\\','') + ' [' + $_.Length + ']' }`, description: "List all markdown notes in second brain" }),
 tools.pwsh({ command: `Get-ChildItem '${B}\\00-收件箱' -File | ForEach-Object { $n=$_.Name; $c=Get-Content -Raw $_.FullName; $hits=([regex]::Matches($c,'已整理')).Count; "$n : 已整理标记 $hits 处" }`, description: "Count processed markers in inbox" }),
 tools.pwsh({ command: `cd '${B}'; git log --oneline --since='2026-10-12' ; echo '=== changed files since 10-12 ==='; git diff --name-status HEAD@{2026-10-12} HEAD 2>&1 | Select-Object -First 40`, description: "Show recent second brain changes" }),
]);
console.log("### all notes\n" + t(mdList));
console.log("\n### inbox processed markers\n" + t(notDone));
console.log("\n### since 10-12\n" + t(gitDelta).slice(0, 2000));
